/**
 * Brand-owned settings (name, package, icons, splash) come from brand/brand.json;
 * everything else stays in app.json. Icons are generated by `pnpm brand`.
 *
 * Changing ids.androidPackage after tablets are in use makes the new APK a
 * different app: it installs beside the old one, unpaired, with an empty queue.
 */
const brand = require('../../brand/brand.json')

/**
 * One version for the whole release: the tablet app takes the counter app's
 * (packages/desktop/package.json, set by `pnpm release`). The versionCode is
 * derived from it so it always goes up — Android refuses an update otherwise.
 * Same formula as androidVersionCode() in packages/shared/src/changelog.ts.
 */
const { version } = require('../desktop/package.json')
const [major, minor, patch] = version.split('.').map(Number)
const versionCode = major * 10000 + minor * 100 + patch

module.exports = ({ config }) => ({
  ...config,
  name: brand.productName,
  version,
  icon: './assets/icon.png',
  android: {
    ...config.android,
    versionCode,
    package: brand.ids.androidPackage,
    adaptiveIcon: {
      foregroundImage: './assets/adaptive-icon.png',
      monochromeImage: './assets/monochrome-icon.png',
      backgroundColor: brand.colors.primary,
    },
  },
  plugins: [
    ...config.plugins,
    ['expo-splash-screen', {
      image: './assets/splash-icon.png',
      imageWidth: 160,
      backgroundColor: brand.colors.splashBackground,
    }],
  ],
})
